  remoteLevel(level) {
    let message;
    let background;
    if (level === 1) {
      message = 'online interview';
      background = '#d8d92f';
    } else if (level === 2) {
      message = 'remote';
      background = '#ffb74d';
    } else if (level === 3) {
      message = 'remote 100%';
      background = '#d94e87';
    }

    return (
      <span
        style={{
          color: 'white',
          background: background,
          margin: '0 0 0 4px',
          padding: '3px 7px 3px 7px',
          borderRadius: '7px',
          whiteSpace: 'nowrap',
          fontWeight: '400',
          lineHeight: '11px',
        }}
      >
        {message}
      </span>
    )
