  selected: PropTypes.any,
  classes: PropTypes.any,
  style: PropTypes.shape({borderLeft: PropTypes.any}),
  onClick: PropTypes.func,
  job: PropTypes.any,
  currentJob: PropTypes.any,
  date: PropTypes.any
};

